'use client';

import React, { useState } from 'react';
import { useCart } from '@/context/CartContext';
import { calculateRecommendedSize } from '@/lib/utils';
import { X, Sparkles, Ruler, CheckCircle2, ArrowRight } from 'lucide-react';

type SmartSizeFinderModalProps = {
  onSelectSizeFilter?: (size: string) => void;
};

export default function SmartSizeFinderModal({ onSelectSizeFilter }: SmartSizeFinderModalProps) {
  const { sizeCalculatorOpen, setSizeCalculatorOpen } = useCart();
  const [gender, setGender] = useState<'WOMEN' | 'MEN'>('WOMEN');
  const [height, setHeight] = useState<number>(gender === 'WOMEN' ? 160 : 172);
  const [weight, setWeight] = useState<number>(gender === 'WOMEN' ? 70 : 85);

  if (!sizeCalculatorOpen) return null;

  const result = calculateRecommendedSize(gender, height, weight);

  return (
    <div className="fixed inset-0 z-50 bg-black/70 backdrop-blur-xs flex items-center justify-center p-4 overflow-y-auto">
      <div className="bg-white rounded-3xl max-w-xl w-full p-6 md:p-8 shadow-2xl relative animate-in zoom-in-95 duration-200">
        
        {/* Close Button */}
        <button
          onClick={() => setSizeCalculatorOpen(false)}
          className="absolute top-5 right-5 p-2 text-neutral-400 hover:text-black hover:bg-neutral-100 rounded-full transition-all"
        >
          <X className="w-5 h-5" />
        </button>

        {/* Modal Header */}
        <div className="flex items-center gap-2 mb-2">
          <div className="p-2 bg-pink-100 text-[#e5677d] rounded-xl">
            <Ruler className="w-5 h-5" />
          </div>
          <div>
            <h3 className="text-lg md:text-xl font-black text-neutral-900 tracking-tight">
              TƯ VẤN CHỌN SIZE THÔNG MINH
            </h3>
            <p className="text-xs text-neutral-500">
              Thuật toán đối chiếu thông số từ 10.000+ khách hàng Bigsize thực tế
            </p>
          </div>
        </div>

        {/* Form Inputs */}
        <div className="mt-6 space-y-6">
          
          {/* Gender Selector */}
          <div>
            <label className="block text-xs font-bold text-neutral-700 uppercase tracking-wider mb-2">
              1. Bạn đang chọn đồ cho ai?
            </label>
            <div className="grid grid-cols-2 gap-3">
              <button
                type="button"
                onClick={() => {
                  setGender('WOMEN');
                  setHeight(160);
                  setWeight(70);
                }}
                className={`py-3 px-4 rounded-xl font-bold text-sm border-2 transition-all cursor-pointer flex items-center justify-center gap-2 ${
                  gender === 'WOMEN'
                    ? 'border-[#e5677d] bg-pink-50/70 text-[#e5677d]'
                    : 'border-neutral-200 text-neutral-600 hover:border-neutral-300'
                }`}
              >
                <span>👗 Thời Trang Nữ (55 - 95kg)</span>
              </button>

              <button
                type="button"
                onClick={() => {
                  setGender('MEN');
                  setHeight(172);
                  setWeight(85);
                }}
                className={`py-3 px-4 rounded-xl font-bold text-sm border-2 transition-all cursor-pointer flex items-center justify-center gap-2 ${
                  gender === 'MEN'
                    ? 'border-neutral-900 bg-neutral-900 text-white'
                    : 'border-neutral-200 text-neutral-600 hover:border-neutral-300'
                }`}
              >
                <span>👔 Thời Trang Nam (65 - 130kg)</span>
              </button>
            </div>
          </div>

          {/* Sliders: Height and Weight */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-neutral-50 p-4 rounded-2xl border border-neutral-200">
            {/* Height */}
            <div>
              <div className="flex justify-between items-center mb-2">
                <span className="text-xs font-bold text-neutral-700">Chiều cao (cm):</span>
                <span className="text-sm font-black text-neutral-900 bg-white px-2.5 py-1 rounded-lg border border-neutral-200 shadow-2xs">
                  {height} cm
                </span>
              </div>
              <input
                type="range"
                min={gender === 'WOMEN' ? 145 : 155}
                max={gender === 'WOMEN' ? 180 : 195}
                value={height}
                onChange={(e) => setHeight(Number(e.target.value))}
                className="w-full accent-[#080808] cursor-pointer"
              />
              <div className="flex justify-between text-[10px] text-neutral-400 mt-1">
                <span>{gender === 'WOMEN' ? '145 cm' : '155 cm'}</span>
                <span>{gender === 'WOMEN' ? '180 cm' : '195 cm'}</span>
              </div>
            </div>

            {/* Weight */}
            <div>
              <div className="flex justify-between items-center mb-2">
                <span className="text-xs font-bold text-neutral-700">Cân nặng (kg):</span>
                <span className="text-sm font-black text-[#e5677d] bg-white px-2.5 py-1 rounded-lg border border-neutral-200 shadow-2xs">
                  {weight} kg
                </span>
              </div>
              <input
                type="range"
                min={gender === 'WOMEN' ? 50 : 60}
                max={gender === 'WOMEN' ? 100 : 135}
                value={weight}
                onChange={(e) => setWeight(Number(e.target.value))}
                className="w-full accent-[#e5677d] cursor-pointer"
              />
              <div className="flex justify-between text-[10px] text-neutral-400 mt-1">
                <span>{gender === 'WOMEN' ? '50 kg' : '60 kg'}</span>
                <span>{gender === 'WOMEN' ? '100 kg' : '135 kg'}</span>
              </div>
            </div>
          </div>

          {/* RECOMMENDATION RESULT BOX */}
          <div className="bg-gradient-to-br from-neutral-900 to-neutral-800 text-white rounded-2xl p-5 shadow-lg relative overflow-hidden">
            <div className="flex items-start justify-between">
              <div>
                <span className="text-[11px] font-bold text-pink-300 uppercase tracking-widest flex items-center gap-1">
                  <Sparkles className="w-3.5 h-3.5" />
                  KẾT QUẢ ĐỀ XUẤT CHUẨN XÁC
                </span>
                <div className="mt-1 flex items-baseline gap-2">
                  <h4 className="text-3xl font-black text-white">
                    SIZE: {result.recommendedSize}
                  </h4>
                  {result.alternativeSize && (
                    <span className="text-xs text-neutral-300">
                      (hoặc {result.alternativeSize})
                    </span>
                  )}
                </div>
              </div>
              <div className="bg-white/10 px-3 py-1.5 rounded-full text-xs font-bold text-emerald-400 flex items-center gap-1">
                <CheckCircle2 className="w-4 h-4" />
                <span>Độ chuẩn {result.confidenceScore}%</span>
              </div>
            </div>

            <p className="text-xs text-neutral-300 mt-3 pt-3 border-t border-white/10 leading-relaxed">
              💡 <strong>Lời khuyên stylist:</strong> {result.fitAdvice}
            </p>
          </div>
        </div>

        {/* Modal Actions */}
        <div className="mt-6 flex flex-col sm:flex-row gap-3">
          <button
            onClick={() => {
              if (onSelectSizeFilter) {
                onSelectSizeFilter(result.recommendedSize);
              }
              setSizeCalculatorOpen(false);
            }}
            className="flex-1 bg-[#080808] hover:bg-neutral-800 text-white font-bold text-sm py-3.5 px-6 rounded-xl transition-all flex items-center justify-center gap-2 cursor-pointer shadow-md"
          >
            <span>Xem Các Mẫu Size {result.recommendedSize} Ngay</span>
            <ArrowRight className="w-4 h-4" />
          </button>
          
          <button
            onClick={() => setSizeCalculatorOpen(false)}
            className="py-3.5 px-6 border border-neutral-300 rounded-xl text-neutral-700 hover:bg-neutral-100 font-semibold text-sm transition-colors"
          >
            Đóng
          </button>
        </div>

      </div>
    </div>
  );
}

